import type {
  CopilotChatReference,
  PullRequestFilesChangedReference,
} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {PullRequestFilesChangedPreview} from './PullRequestFilesChangedPreview'

export function PullRequestFilesChangedPluginPreview({reference}: {reference: CopilotChatReference}) {
  const {headSha, basePath, isSessionRunning, isSessionReadonly, agentDisplayName} =
    reference as PullRequestFilesChangedReference

  return (
    <PullRequestFilesChangedPreview
      headSha={headSha}
      basePath={basePath}
      isSessionRunning={isSessionRunning}
      isSessionReadonly={isSessionReadonly}
      agentDisplayName={agentDisplayName}
    />
  )
}
