import type {ImmersivePlugin} from '@github-ui/copilot-chat/plugin'
import {PullRequestFilesChangedPluginPreview} from './components/task-view/PullRequestFilesChangedPluginPreview'
import {PullRequestOverviewPluginPreview} from './components/task-view/PullRequestOverviewPluginPreview'
import {TaskViewWrapper} from './components/task-view/TaskView'
import {TASK_VIEW_COMPONENT_ID, TASKS_IN_CHAT_COMPONENT_ID, TASKS_PLUGIN_ID, TASKS_PLUGIN_NAME} from './utils/constants'
import {TaskChatSuspendedWrapper} from './components/task-view/TaskChat'

const TASK_REGEX = /\/copilot\/tasks\/pull\/([a-zA-Z0-9-_]+)/
const TASKS_IN_CHAT_REGEX = /\/copilot\/t\/([a-zA-Z0-9-_]+)\/([^/]+)\/([a-zA-Z0-9-_]+)/

export class TasksPlugin implements ImmersivePlugin {
  id = TASKS_PLUGIN_ID

  displayName = TASKS_PLUGIN_NAME

  skipSyncRouteToThread = true

  components = [
    {id: TASK_VIEW_COMPONENT_ID, Component: TaskViewWrapper, routes: [TASK_REGEX]},
    {id: TASKS_IN_CHAT_COMPONENT_ID, Component: TaskChatSuspendedWrapper, routes: [TASKS_IN_CHAT_REGEX]},
  ]

  get previewComponents() {
    return {
      'pr-overview': PullRequestOverviewPluginPreview,
      'pr-files-changed': PullRequestFilesChangedPluginPreview,
    }
  }
}
