import {sendEvent} from '@github-ui/hydro-analytics'
import {useNavigableRef} from '@github-ui/navigable-ref'
import {SidebarExpandIcon} from '@primer/octicons-react'
import {IconButton} from '@primer/react'

export function PreviewPaneButton({
  isContentPreviewOpen,
  openPreviewPane,
}: {
  isContentPreviewOpen: boolean
  openPreviewPane: () => void
}) {
  const buttonRef = useNavigableRef<HTMLButtonElement>()

  return (
    !isContentPreviewOpen && (
      <IconButton
        icon={SidebarExpandIcon}
        aria-label="Open workbench"
        size="small"
        onClick={() => {
          openPreviewPane()
          sendEvent('dotcom_chat.activate', {
            target: 'OPEN_PREVIEW_PANE_BUTTON',
            mode: 'immersive',
            context: 'agent_sessions',
          })
        }}
        ref={buttonRef}
      />
    )
  )
}
