import type {CopilotChatReference} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {PullRequestOverviewPreview} from './PullRequestOverviewPreview'

export function PullRequestOverviewPluginPreview({reference}: {reference: CopilotChatReference}) {
  if (reference.type !== 'pr-overview') return null

  return <PullRequestOverviewPreview {...reference} />
}
