import {useAlive} from '@github-ui/use-alive'
import throttle from 'lodash-es/throttle'
import {useMemo} from 'react'

interface AliveEventPayload {
  event_updates?: {
    git_updated?: boolean
    body_updated?: boolean
    title_updated?: boolean
  }
}

const THROTTLE_INTERVAL_MS = 2000

/**
 * Hook that subscribes to pull request alive updates and triggers appropriate refetch callbacks
 * based on the type of update that occurred.
 *
 * @param aliveChannel - The signed alive channel for the pull request (from PR data)
 * @param onPullRequestUpdate - Callback to trigger when git or general updates occur (head_sha or base_sha or title changes)
 * @param onBodyUpdate - Callback to trigger when body updates occur
 */
export function usePullRequestAliveUpdates(
  aliveChannel: string | undefined,
  onPullRequestUpdate: () => void,
  onBodyUpdate: () => void,
) {
  const throttledPullRequestRefetch = useMemo(
    () => throttle(onPullRequestUpdate, THROTTLE_INTERVAL_MS, {leading: false, trailing: true}),
    [onPullRequestUpdate],
  )

  const throttledBodyRefetch = useMemo(
    () => throttle(onBodyUpdate, THROTTLE_INTERVAL_MS, {leading: false, trailing: true}),
    [onBodyUpdate],
  )

  const handleAliveEvent = (event: AliveEventPayload) => {
    if (event.event_updates?.git_updated || event.event_updates?.title_updated) {
      throttledPullRequestRefetch()
    }
    if (event.event_updates?.body_updated) {
      throttledBodyRefetch()
    }
  }

  useAlive(aliveChannel, handleAliveEvent)
}
